package app.bikriflow.mobile.data
import android.content.Context
data class BusinessSettings(val onboardingComplete: Boolean = false, val businessName: String = "My Store", val currency: String = "৳", val ownerName: String = "", val phone: String = "", val language: String = "en")
class SettingsStore(context: Context) { private val prefs = context.getSharedPreferences("bikriflow_settings", Context.MODE_PRIVATE); fun read(): BusinessSettings = BusinessSettings(prefs.getBoolean("onboarding_complete", false), prefs.getString("business_name", "My Store") ?: "My Store", prefs.getString("currency", "৳") ?: "৳", prefs.getString("owner_name", "") ?: "", prefs.getString("phone", "") ?: "", prefs.getString("language", "en") ?: "en"); fun save(settings: BusinessSettings) { prefs.edit().putBoolean("onboarding_complete", settings.onboardingComplete).putString("business_name", settings.businessName).putString("currency", settings.currency).putString("owner_name", settings.ownerName).putString("phone", settings.phone).putString("language", settings.language).apply() } }
